/* Checks the host abi_version against NATCATTY_ABI_VERSION. On a mismatch
 * it logs one error line and returns -1; on success it returns 0. Call it
 * from natcatty_init and fail init when it does not return 0. */
natcatty_i32 natcatty_guest_init(void);

