static const char natcatty_abi_mismatch_message[] =
    "plugin ABI mismatch: generated C bindings speak ABI 1\n";

natcatty_i32 natcatty_guest_init(void) {
  if (natcatty_host_abi_version() != NATCATTY_ABI_VERSION) {
    natcatty_host_log(NATCATTY_LOG_LEVEL_ERROR,
        NATCATTY_PTR(natcatty_abi_mismatch_message),
        (natcatty_u32)(sizeof(natcatty_abi_mismatch_message) - 1));
    return -1;
  }
  return 0;
}

